#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v = {3, 1, 4, 1, 5};
    int limit = 2;
    int count = 0;

    for_each(v.begin(), v.end(), [&count, limit](int x) {
        if (x > limit) {
            count++;
        }
    });

    cout << count << endl;
    return 0;
}
